                      onSelect={(index) => actions.selectTrack(index)}
                      className="max-h-56 bg-neo-bg"
                    />
                  </div>
                </div>
              )}
            </ConsentGate>
          </div>
        </div>
      </motion.div>
    </motion.section>
  );
};

export default NeoSplitHero;

