  hidden: { opacity: 0, y: 30, scale: 0.95 },
  visible: { opacity: 1, y: 0, scale: 1, transition: { duration: 0.4 } },
  exit: { opacity: 0, y: -20, scale: 0.95, transition: { duration: 0.3 } },
};

// Composant AlbumCard avec gestion du tap mobile
interface AlbumCardProps {
  album: Album;
  onPlayClick: (e: React.MouseEvent, album: Album) => void;
  normalizeGenre: (style: string | null) => string | null;
  featuredLabel: string;
}

const AlbumCard: React.FC<AlbumCardProps> = ({
  album,
  onPlayClick,
  normalizeGenre,
  featuredLabel,
}) => {
  const [showActions, setShowActions] = useState(false);

  const handleCoverClick = (e: React.MouseEvent) => {
    // Sur mobile, toggle l'affichage des actions
    // On détecte mobile par la largeur de l'écran ou touch event
    const isTouchDevice = "ontouchstart" in window || navigator.maxTouchPoints > 0;
    if (isTouchDevice) {
      e.preventDefault();
      setShowActions((prev) => !prev);
    }
  };

  return (
    <motion.div variants={fadeInUp} layout className="group relative">
      {/* Cover */}
      <div
        className="aspect-square border-4 border-neo-border bg-neo-bg-alt relative mb-6 overflow-hidden shadow-[8px_8px_0px_0px_var(--neo-accent)] group-hover:shadow-[12px_12px_0px_0px_var(--neo-accent)] transition-all duration-300 cursor-pointer"
        onClick={handleCoverClick}
      >
        <div
          className="w-full h-full bg-cover bg-center group-hover:scale-105 transition-transform duration-500"
          style={{ backgroundImage: album.img ? `url(${album.img})` : undefined }}
        />
        {!album.img && (
          <div className="absolute inset-0 flex items-center justify-center">
            <Disc className="w-20 h-20 opacity-20" />
          </div>
        )}
        {/* Overlay with actions - visible on hover (desktop) or tap (mobile) */}
        <div
          className={`absolute inset-0 flex flex-col items-center justify-center gap-4 bg-neo-text/60 transition-opacity duration-300 ${
            showActions ? "opacity-100" : "opacity-0 group-hover:opacity-100"
          }`}
        >
          {/* Play button */}
          {album.spotifyEmbed && (
            <button
              onClick={(e) => {
                e.stopPropagation();
                onPlayClick(e, album);
                setShowActions(false);
              }}
              className="w-16 h-16 bg-[#1DB954] rounded-full flex items-center justify-center border-4 border-neo-border hover:scale-110 active:scale-95 transition-transform shadow-[4px_4px_0px_0px_var(--neo-border)]"
              title="Écouter sur Spotify"
            >
              <Play size={28} className="text-white ml-1" fill="white" />
            </button>
          )}
          {/* View album button */}
          <Link
            href={{ pathname: "/albums/[id]", params: { id: album.id } }}
            onClick={(e) => e.stopPropagation()}
            className="flex items-center gap-2 px-4 py-2 bg-neo-bg text-neo-text font-mono text-sm font-bold uppercase border-2 border-neo-border hover:bg-neo-accent hover:text-neo-text-inverse active:scale-95 transition-all shadow-[3px_3px_0px_0px_var(--neo-border)]"
          >
            <span>Voir album</span>
            <ExternalLink size={14} />
          </Link>
        </div>
        {/* Badge Favori pour les albums épinglés */}
        {album.order !== undefined && album.order < 100 && (
          <div className="absolute top-3 right-3 bg-neo-accent text-neo-text-inverse px-3 py-1 border-2 border-neo-border flex items-center gap-1.5 font-mono text-xs font-bold uppercase shadow-[3px_3px_0px_0px_var(--neo-border)]">
            <Star size={12} className="fill-current" />
            {featuredLabel}
          </div>
        )}
        {/* Indicateur tap sur mobile - visible seulement sur touch devices */}
        <div className="absolute bottom-3 left-1/2 -translate-x-1/2 md:hidden pointer-events-none">
          <div
            className={`px-3 py-1 bg-neo-bg/90 border-2 border-neo-border font-mono text-[10px] uppercase tracking-wider transition-opacity ${
              showActions ? "opacity-0" : "opacity-70"
            }`}
          >
            Tap pour actions
          </div>
        </div>
