import { spotifyPlayerActions } from "@/lib/player/spotifyPlayer";
import { NeoNavbar } from "../NeoNavbar";
import { NeoFooter } from "../NeoFooter";
import { NeoHeroSection } from "../ui/NeoHeroSection";
